import {guidedInstruction} from './session-guidance.js';
import {OBS_CHECKS} from './observation.js';
import {PILOT_FORMS,pilotAssignment} from './pilot-kit.js';
import {SESSION_KEY,SESSION_DAY,sessionChoices,newGuidedSession,restoreGuidedSession,guidedStep,phaseResult,guidedRows,sessionCSV,sessionWorkbook} from './session-kit.js';
const gsRoot=document.querySelector('#app'),gsEscape=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let gsError='';
function gsRead(){const raw=window.fixiverseStorage.getItem(SESSION_KEY);return raw?restoreGuidedSession(JSON.parse(raw)):newGuidedSession();}
function gsSave(a){const s=guidedStep(gsRead(),a);window.fixiverseStorage.setItem(SESSION_KEY,JSON.stringify(s));return s;}
const gsAlias=()=>window.fixiverseProfiles.list().find(p=>p.id===window.fixiverseProfiles.active()).alias;
const gsButton=(text,action,attrs='')=>`<button class="btn" data-session="${action}" ${attrs}>${text}</button>`;
const gsLabel=(x,focus)=>({left:'Top piece',equal:'Same size',right:'Bottom piece',unsure:'Not sure',help:'Asked for math help',skip:'Skipped','not offered':'Not offered'}[x]||x);
function gsChoices(focus,empty=false){return`${empty?'<option value="">Not observed / no additional response</option>':'<option value="" disabled selected>Choose the observed response</option>'}${sessionChoices(focus).map(v=>`<option value="${v}">${gsLabel(v,focus)}</option>`).join('')}`;}
const gsBars=n=>`<svg viewBox="0 0 360 32" role="img" aria-label="One of ${n} equal parts shaded"><rect x="1" y="1" width="358" height="30" fill="#fff" stroke="#355641"/><rect x="1" y="1" width="${358/n}" height="30" fill="#79996c"/>${Array.from({length:n-1},(_,i)=>`<path d="M${1+(i+1)*358/n} 1v30" stroke="#355641"/>`).join('')}</svg>`;
function gsTask(t){return t.pair?`<p>Which shaded piece is bigger?</p><div class="session-bars"><b>Top: 1/${t.pair[0]}</b>${gsBars(t.pair[0])}<b>Bottom: 1/${t.pair[1]}</b>${gsBars(t.pair[1])}</div><p>Same-sized wholes · equal parts · one piece each</p>`:`<p>Which tile comes next?</p><p>Repeating unit: ${t.block.map(v=>`<span class="session-tile">${{sun:'☀',leaf:'❧',star:'★',moon:'☾'}[v]} ${v}</span>`).join('')}</p><div class="session-path">${Array.from({length:t.length},(_,i)=>`<span class="session-tile">${{sun:'☀',leaf:'❧',star:'★',moon:'☾'}[t.block[i%t.block.length]]} ${t.block[i%t.block.length]}</span>`).join('')}<span class="session-tile">?</span></div>`;}
function gsSection(){let s;try{s=gsRead();}catch{return`<section class="tutor-section"><h2>Guided testing session</h2><p>A saved session needs review. Back up this workspace before continuing.</p></section>`;}const r=s.stage==='setup'?null:phaseResult(s,'after');return`<section class="tutor-section guided-entry"><div class="section-heading"><h2>Run a testing session</h2><span>One learner · one saved plan</span></div><p>Script, on-screen tasks, confidence, help and automatic results exports. ${s.stage==='setup'?'Ready to begin.':`Saved at: ${gsEscape(s.stage)}. ${r?.complete?`After: ${r.first}/3 first responses without math help.`:''}`}</p><div class="btn-row">${gsButton(s.stage==='setup'?'Start guided session':'Resume / review session','open')}${gsButton('Export all testing results','export-all')}</div><p>Record the before tasks before showing the scroll story or missions. This guided flow saves responses and calculates exports.</p></section>`;}
function gsShow(){const oldStage=gsRoot.dataset.sessionStage;let s;try{s=gsRead();}catch(e){gsError=e.message;s=null;}location.hash='session';document.title='Fixiverse · Guided tutor session';const prefs=(()=>{try{return JSON.parse(window.fixiverseStorage.getItem('fixiverse-access-v1')||'null')||{};}catch{return {};}})();gsRoot.className='tutor-app storybook-tutor session-screen'+(prefs.large?' large':'')+(prefs.motion?' reduced':'');gsRoot.dataset.sessionStage=s?.stage||'recovery';gsRoot.dataset.sessionTask=String(s?.phases?.[s.stage]?.answers.length??'');
let content='';if(!s)content='<p>Back up your workspace; this record could not be restored safely.</p>';else if(s.stage==='setup')content=`<p class="script">“I’m testing the activity, not you. You can point, talk, use your usual tools, say ‘not sure,’ take a break or stop.”</p><p>Use your normal permission process. One focus per child; usual accommodations are welcome. The plan is fixed after you start. Use a fresh learner profile for a new pilot.</p><form id="guided-setup" class="session-form"><label>Focus<select name="focus"><option>Fraction</option><option>Pattern</option></select></label><label>Form rotation<select name="planIndex">${Array.from({length:8},(_,i)=>`<option value="${i}">${pilotAssignment(i).id}: ${pilotAssignment(i).Before} → ${pilotAssignment(i).After} → ${pilotAssignment(i)['Next-day']}</option>`).join('')}</select></label><label>Device<input name="device" required maxlength="120" placeholder="e.g. learner’s iPad"></label><label>Browser<input name="browser" required maxlength="120" placeholder="e.g. Safari"></label><label>Testing environment<select name="environment"><option>Actual device</option><option>Browser viewport simulation</option><option>Not specified</option></select></label><label>Input method<input name="input" maxlength="120" placeholder="Touch / keyboard / switch"></label><label>Usual accessibility tools<input name="tools" maxlength="120" placeholder="Tool names or none"></label><label>Prior exposure / accommodations<textarea name="prior" maxlength="1000"></textarea></label><button class="btn" type="submit">Save plan and begin before tasks</button></form>`;
else if(['before','after','nextday'].includes(s.stage)){const p=s.phases[s.stage],i=p.answers.length;content=`<p class="eyebrow">${s.focus} · Form ${p.form} · ${s.stage==='nextday'?'Next-day':s.stage} · ${i}/3 responses recorded</p>`;
if(p.confidence===null)content+=`<p class="script">“How sure do you feel about trying a new puzzle like these?”</p><p>Ask neutrally. A higher number is not a better child. Skip is welcome.</p><div class="btn-row">${[[1,'1 · Not sure yet'],[2,'2 · A little sure'],[3,'3 · Ready to try'],['skip','Skip this question']].map(([v,t])=>gsButton(t,'confidence',`data-value="${v}"`)).join('')}</div>`;
else if(i<3)content+=`<p class="session-instruction">Record the first response before math instruction. Collect all three first responses before correcting. Access accommodations stay available. If stopping, leave this page to resume later, or record remaining tasks as Not offered.</p><article class="session-puzzle">${gsTask(PILOT_FORMS[p.form][s.focus][i])}</article><form id="guided-answer" class="session-form"><label>Observed first response<select name="response" required>${gsChoices(s.focus)}</select></label><label>Math help before this response<select name="help"><option value="0">0 · No math instruction</option><option value="1">1 · Conceptual prompt</option><option value="2">2 · Strategy / explanation</option><option value="3">3 · Worked answer</option></select></label><label>Access support / context<textarea name="access" maxlength="1000" placeholder="Read label, AAC, or other support; do not include a diagnosis"></textarea></label><button class="btn" type="submit">Save response and continue</button></form>`;
else content+=`<h2>First responses are saved.</h2><p>No correctness feedback was shown during collection. You may now offer support if appropriate. Optional supported responses below never replace first responses.</p><form id="guided-finish" class="session-form">${p.answers.map((a,i)=>`<label>Task ${i+1} supported response (optional)<select name="supported${i}">${gsChoices(s.focus,true)}</select></label>`).join('')}<label>Phase notes / deviations<textarea name="note" maxlength="1000"></textarea></label><button class="btn" type="submit">Finish ${s.stage==='nextday'?'next-day':s.stage} tasks</button></form>`;}
else if(s.stage==='play')content=`<h2>Let the learner investigate.</h2><p class="script">“Open a book and show me what you think you can do next. You can ask for help.”</p><p>Use ${s.focus==='Fraction'?'Fraction Foundry':'Pattern Grove'} for about 10 to 15 minutes, with breaks or stopping whenever needed. Use the observation controls to mark interface instructions, math help and access support separately. When finished, return to Tutor workspace → Resume session.</p><div class="btn-row">${gsButton(s.play.started===null?'Start play + observation':'Return to mission','play')}${s.play.started!==null?'<button class="quiet" data-observe="manage">Review observation notes</button>':''}</div>${s.play.started!==null?`<form id="guided-play-finish" class="session-form"><label>Observation completeness<select name="completeness"><option>Partial</option><option>Complete</option><option>Not run</option></select></label><label>Play notes / other activities / stopping reason<textarea name="note" maxlength="1000"></textarea></label><button class="btn" type="submit">Finish play and begin after tasks</button></form>`:''}`;
else if(s.stage==='waiting'){const unlock=s.phases.after.finished+SESSION_DAY;content=`<h2>Today’s visit is saved.</h2><p>Next-day tasks unlock <b>${gsEscape(new Date(unlock).toLocaleString())}</b>, 24 hours after the after tasks. Ideally return within 24 to 48 hours and before more practice.</p><p>The next form is ${pilotAssignment(s.planIndex)['Next-day']}. Reopen this learner and Resume session tomorrow. Missing follow-up stays missing.</p>${gsButton(Date.now()>=unlock?'Begin next-day tasks':'Check next-day availability','nextday')}`;}
else content='<h2>All three task phases are recorded.</h2><p>Review the results below. This small pilot describes task responses and support; it is not a validated assessment or proof of causal learning gains.</p>';
if(s?.phases?.[s.stage]?.answers.length&&s.phases[s.stage].finished===null)content+=`<details class="session-review"><summary>Correct the previous entry</summary><p>Use this only to correct a recording mistake. The original entry and reason stay in the export.</p><form id="guided-correct" class="session-form"><label>Why is this entry being corrected?<textarea name="reason" required maxlength="1000"></textarea></label><button class="btn" type="submit">Correct previous entry</button></form></details>`;
if(s&&s.stage!=='setup'){content+=`<details class="session-review"><summary>Tutor-only results · keep closed during tasks</summary><table><thead><tr><th>Phase</th><th>Correct without math help / offered</th><th>Confidence</th><th>Status</th></tr></thead><tbody>${['before','after','nextday'].map(k=>{const r=phaseResult(s,k);return`<tr><td>${k}</td><td>${r?`${r.first}/${r.offered}`:'Not recorded'}</td><td>${s.phases[k]?.confidence==='skip'?'Skipped':r?.confidence??'Not recorded'}</td><td>${s.phases[k]?.finished!=null?`Finished; ${r?.offered??0}/3 offered`:r?'In progress':'Not recorded'}</td></tr>`;}).join('')}</tbody></table><p>A matching response after math help is not counted as independently correct. Access support is recorded separately.</p></details>`;}
gsRoot.innerHTML=`<header><div class="brand">fixiverse <span class="workspace-label">TUTOR SESSION</span></div>${gsButton('Tutor dashboard','back')}</header><main id="main" class="session-shell"><div class="eyebrow">${gsEscape(gsAlias())} · SAVED IN THIS BROWSER</div><h1 id="screen-title" tabindex="-1">One small session. Step by step.</h1><nav class="session-steps" aria-label="Testing session phases">${['setup','before','play','after','waiting','nextday','complete'].map(k=>`<span ${s?.stage===k?'aria-current="step"':''}>${({setup:'1. Setup',before:'2. Before',play:'3. Explore',after:'4. After',waiting:'5. Return tomorrow',nextday:'6. Next-day',complete:'7. Review'})[k]}</span>`).join('')}</nav><p id="session-error" role="status">${gsEscape(gsError)}</p><section class="session-next" aria-label="Tutor next step"><span class="eyebrow">YOUR NEXT STEP</span><p>${guidedInstruction(s)}</p></section><section class="session-current">${content}</section><div class="session-export"><h2>Export recorded results</h2><label>Export scope <select id="session-export-scope"><option value="current">Selected learner only</option><option value="all">All learners with guided sessions</option></select></label>${gsButton('Download results workbook (.xml)','export')}${gsButton('Download summary CSV','csv')}<p>Exports use the selected scope and include calculated results, recorded answers, and observation notes. Open the XML workbook in Excel or LibreOffice. No manual transfer into the old sheet is needed. Downloaded files contain private learning observations.</p><button class="quiet" data-recovery="open">Back up / restore workspace</button></div></main>`;const reduced=prefs.motion||matchMedia('(prefers-reduced-motion: reduce)').matches;const contentRoot=gsRoot.querySelector('.session-current');if(!reduced)contentRoot?.animate([{opacity:.4,transform:'translateY(6px)'},{opacity:1,transform:'translateY(0)'}],{duration:180,easing:'ease-out'});const task=gsRoot.querySelector('.session-puzzle');if(task&&oldStage===s?.stage){task.tabIndex=-1;task.setAttribute('aria-label','Current assessment task');task.focus({preventScroll:true});task.scrollIntoView({block:'start',behavior:reduced?'instant':'smooth'});}else{document.querySelector('#screen-title').focus({preventScroll:true});window.scrollTo(0,0);}gsError='';}
function gsDownload(kind,scope=document.querySelector('#session-export-scope')?.value||'current'){const entries=window.fixiverseProfiles.list().filter(p=>scope==='all'||p.id===window.fixiverseProfiles.active()).map(p=>({alias:p.alias,model:window.fixiverseProfiles.read(p.id,SESSION_KEY),observations:window.fixiverseProfiles.read(p.id,'fixiverse-observations-v1')})),rows=guidedRows(entries),barriers=[['Learner','Phase','Screen','Kind','Severity','Quantity','Tried','Help','Note','Status','Excluded']],checks=[['Learner','Device','Browser','Tools','Check','Status','Evidence']];
for(const e of entries)for(const visit of e.observations?.sessions||[]){for(const v of visit.events)barriers.push([e.alias,visit.phase,v.screen,v.kind,v.severity,v.quantity,v.tried,v.help,v.note,v.status,v.voided]);for(const [key,label]of OBS_CHECKS){const v=visit.checks[key]||{status:'Not run',note:''};checks.push([e.alias,visit.device,visit.browser,visit.tools,label,v.status,v.note]);}}
const corrections=[['Learner','Phase','Task','Previous response','Previous math help','Reason','Correction time ISO']];for(const e of entries)for(const [phase,p]of Object.entries(e.model?.phases||{}))for(const c of p.corrections||[])corrections.push([e.alias,phase,c.task,c.previous.response,c.previous.help,c.reason,new Date(c.at).toISOString()]);
const content=kind==='csv'?sessionCSV(rows.summary):sessionWorkbook({Summary:rows.summary,Sessions:rows.sessions,Answers:rows.answers,Barriers:barriers,DeviceChecks:checks,Corrections:corrections}),url=URL.createObjectURL(new Blob(['\ufeff'+content],{type:kind==='csv'?'text/csv;charset=utf-8':'application/xml;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download=`fixiverse-guided-results.${kind==='csv'?'csv':'xml'}`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.querySelector('#announcement').textContent='Guided results downloaded. No invented scores were added.';}
document.addEventListener('click',e=>{const b=e.target.closest('[data-session]');if(!b)return;try{const a=b.dataset.session;if(a==='open'){gsShow();return;}if(a==='back'){location.hash='tutor';window.fixiverseTutor.show();return;}if(a==='export'||a==='csv'||a==='export-all'){gsDownload(a==='csv'?'csv':'export',a==='export-all'?'all':undefined);return;}if(a==='confidence')gsSave({type:'confidence',value:b.dataset.value==='skip'?'skip':+b.dataset.value});if(a==='nextday')gsSave({type:'nextday'});if(a==='play'){const s=gsRead(),observation=window.fixiverseObservation.beginPilot(s);gsSave({type:'play',observation});window.fixiverseLaunch(s.focus==='Fraction'?'fraction':'pattern');return;}gsShow();}catch(err){const status=document.querySelector('#session-error')||document.querySelector('#announcement');status.textContent=err.message;}});
document.addEventListener('submit',e=>{const f=e.target;if(!f.id?.startsWith('guided-'))return;e.preventDefault();const d=Object.fromEntries(new FormData(f));try{if(f.id==='guided-setup')gsSave({type:'setup',...d});if(f.id==='guided-correct')gsSave({type:'correct-last',reason:d.reason});if(f.id==='guided-answer')gsSave({type:'answer',...d,help:+d.help});if(f.id==='guided-finish')gsSave({type:'finish-phase',supported:[d.supported0,d.supported1,d.supported2],note:d.note});if(f.id==='guided-play-finish'){window.fixiverseObservation.endPilot(gsRead().play.observation);gsSave({type:'finish-play',...d});}gsShow();}catch(err){document.querySelector('#session-error').textContent=err.message;}});
window.fixiverseSession={section:gsSection,show:gsShow};
